declare(strict_types=1);require __DIR__.'/app/commercial.php';if(!current_user()){$_SESSION['after_login']='commercial-import-public';flash('error','Sign in to save this generated document to Commercial.');redirect('login');}$user=require_verified();$data=$_SESSION['public_commercial_draft']??null;if(!$data){flash('error','Your one-off document is no longer available to save.');redirect('quote-invoice-generator');}$d=$data['document'];$customerId=commercial_customer_save($user,['name'=>$d['customer_name'],'email'=>$d['customer_email'],'phone'=>$d['customer_phone'],'billing_address'=>$d['customer_address'],'tin'=>$d['customer_tin'],'currency'=>$d['currency']]);$input=['customer_id'=>$customerId,'currency'=>$d['currency'],'issue_date'=>$d['issue_date'],'valid_until'=>$d['valid_until'],'due_date'=>$d['due_date'],'customer_po'=>$d['customer_po'],'customer_reference'=>$d['customer_reference'],'payment_terms'=>$d['payment_terms'],'notes'=>$d['notes'],'adjustment_total'=>$d['adjustment_total'],'item_description'=>array_column($d['items'],'description'),'item_quantity'=>array_column($d['items'],'quantity'),'item_unit'=>array_column($d['items'],'unit'),'item_duration'=>array_column($d['items'],'duration'),'item_rate'=>array_column($d['items'],'rate'),'item_discount'=>array_column($d['items'],'discount_rate'),'item_tax'=>array_column($d['items'],'tax_rate')];$id=commercial_document_save($user,$input,$d['document_type']);unset($_SESSION['public_commercial_draft']);flash('success','Your generated document was saved as a Commercial draft.');redirect('commercial?view=document&id='.rawurlencode($id));
